// TH14 v1.00b Extra (stage 7) mid-stage wave 04.
// Source: st07.ecl.txt MainSub03 754-775 (entry), GirlC01 343-365 and
// GirlC01_at 367-398 (dependency closure). Card frame 0 starts the segment
// clock; source attack t=0 sits at OPENING_BUFFER.
//
// Omitted per shared policy: chapter/reward drops, ANM/drop calls, bullet
// birth slowdown, invulnerable-window birth phase. The ANIM birth retreat
// (position -= 4 * initial speed) is kept as a spawn-position shift.
// Source etEx records on this emitter are ANIM (a=1), BRIGHT (a=1) and
// SPEEDUP; only the ANIM retreat has physical effect and is kept above.

const TIME_LIMIT: int = 2124;
const OPENING_BUFFER: int = 120;

// MainSub03 756-758: three GirlC01 in a row, then one every 160 frames.
async sub girl_schedule() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -32fx, 800, 0, 0, 0, girl_main);
    _ = spawn_enemy(-128fx, -32fx, 800, 0, 0, 0, girl_main);
    _ = spawn_enemy(128fx, -32fx, 800, 0, 0, 0, girl_main);
    wait(160);                                        // 759
    _ = spawn_enemy(0fx, -32fx, 800, 0, 0, 0, girl_main);
    wait(160);                                        // 761
    _ = spawn_enemy(-144fx, -32fx, 800, 0, 0, 0, girl_main);
    _ = spawn_enemy(144fx, -32fx, 800, 0, 0, 0, girl_main);
    wait(160);                                        // 764
    _ = spawn_enemy(128fx, -32fx, 800, 0, 0, 0, girl_main);
    wait(160);                                        // 766
    _ = spawn_enemy(32fx, -32fx, 800, 0, 0, 0, girl_main);
    _ = spawn_enemy(-32fx, -32fx, 800, 0, 0, 0, girl_main);
    wait(160);                                        // 769
    _ = spawn_enemy(-128fx, -32fx, 800, 0, 0, 0, girl_main);
    wait(160);                                        // 771
    _ = spawn_enemy(-160fx, -32fx, 800, 0, 0, 0, girl_main);
    _ = spawn_enemy(160fx, -32fx, 800, 0, 0, 0, girl_main);
}

// GirlC01 343-365 (anmSelect/dropMain/dropExtra omitted).
async sub girl_main() {
    set_invuln(65535);
    set_hurtbox(12fx);                                // setHurtbox(24,24): 24*0.5
    set_hitbox(8fx);                                  // setHitbox(16,16): 16*0.5
    move_vel(0, 90deg, 1.5fx, EASE_LINEAR);           // moveVel(pi/2, 1.5)
    move_vel(80, aim_player(), 0.1fx, EASE_QUAD_IN);  // moveVelTime(80,1,ANGLE_PLAYER,0.1)
    wait(60);                                         // 355
    spawn girl_emit();                                // 356 @GirlC01_at() async
    wait(200);                                        // 357
    move_vel(80, 90deg, 1fx, EASE_QUAD_IN);           // moveVelTime(80,1,pi/2,1.0)
    loop { wait(1000); }                              // GirlC01_424/404 wait loop
}

// GirlC01_at 367-398: one emitter, 180 volleys of 5 bullets every 2 frames.
// Bullet source type 5 -> TH14_BALL2 (same-number slot), original color 2.
// Speed: etCount(1,1) keeps only the first etSpeed endpoint (1.5).
async sub girl_emit() {
    sh_reset(0);
    sh_sprite(0, TH14_BALL2, 2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 1, 1);
    sh_angle(0, 0deg, 0deg);                          // etAngle(0, 0, pi/6), one way
    sh_speed(0, 1.5fx, 0fx);                          // etSpeed(1.5, 1.0), one layer

    var c: angle = (rand(65536) - 32768) as angle;    // 379 %C = %RANDRAD
    var d: int = 180;                                 // 380 $D = 180

    while d > 0 {
        d = d - 1;
        // 383 circlePos(%A,%B,%C,%RANDF*64)
        var u1: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;
        var px: fx = u1 * 64fx * cos(c);
        var py: fx = u1 * 64fx * sin(c);
        // 385 etAngle(0, %RANDRAD, 0)
        var a: angle = (rand(65536) - 32768) as angle;
        // 384 etOffsetAbs(0, %A+%FINAL_X, %B+%FINAL_Y); ANIM retreat 4*1.5px
        sh_offset_abs(0, $self_x + px - 6fx * cos(a),
                      $self_y + py - 6fx * sin(a));
        sh_angle(0, a, 0deg);
        // 386-392: $E = 5; etOffsetRad + etOn per bullet
        var e: int = 5;
        while e > 0 {
            e = e - 1;
            var ra: angle = (rand(65536) - 32768) as angle;
            var rd: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;
            sh_offset_rad(0, ra, rd * 8fx);
            sh_fire(0);
        }
        // 393 %C += pi/2 * %RANDF + pi/4
        var cu: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;
        c = c + (((cu * 16384fx) as int + 8192) as angle);
        wait(2);                                      // 394
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, girl_schedule, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
